function.arguments:
{"script":"mkdir -p /tmp/workspace_check
echo "Timestamp: $(date)" > /tmp/workspace_check/precheck.txt
ls -ld /working >> /tmp/workspace_check/precheck.txt 2>&1 || echo "Access denied or not found" >> /tmp/workspace_check/precheck.txt
find /working -exec stat -c "%F | %s | %y | %n" {} + > /tmp/workspace_check/entries_list.txt
awk -F' \\| ' '{
    n = split($4, a, "/");
    if(a[n] == "workspace") {
        print $4 " - " $1
    }
}' /tmp/workspace_check/entries_list.txt > /tmp/workspace_check/candidates.txt
grep "regular file" /tmp/workspace_check/candidates.txt > /tmp/workspace_check/result_prep.txt || true
cat /tmp/workspace_check/result_prep.txt
"}
